 94→// timeAgo formats a time as a human-readable relative duration.
 95→func timeAgo(t time.Time) string {
 96→	d := time.Since(t)
 97→	switch {
 98→	case d < time.Minute:
 99→		return "just now"
100→	case d < time.Hour:
101→		m := int(d.Minutes())
102→		return fmt.Sprintf("%dm ago", m)
103→	case d < 24*time.Hour:
104→		h := int(d.Hours())
105→		return fmt.Sprintf("%dh ago", h)
106→	default:
107→		days := int(d.Hours() / 24)
108→		return fmt.Sprintf("%dd ago", days)
109→	}
110→}
